sys_script.script:
(function(current, previous) {
    try {
        var classifier = new AIExceptionClassifier(current);
        classifier.classify();

        // Re-fetch the record to get the updated fields after classify()
        var gr = new GlideRecord('x_1956908_wareho_0_exception');
        if (gr.get(current.getUniqueValue())) {
            var insights = new AIRootCauseInsights(gr);
            insights.analyze();
        }
    } catch (e) {
        gs.error('AI Classify Exception BR: Error during AI classification - ' + e.message);
    }
})(current, previous);
